'use strict';

// MODULES //

var sqrt = require( '@stdlib/math/base/special/sqrt' );


// MAIN //

/**
* Computes scaling using already validated normalized views.
* @private
* @param {integer} uplo - numeric triangle
* @param {NonNegativeInteger} N - order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Float64Array} S - vector output
* @param {integer} ss - vector stride
* @param {integer} os - vector offset
* @param {Float64Array} SCOND - scalar output
* @param {integer} oc - scalar offset
* @param {Float64Array} AMAX - scalar output
* @param {integer} om - scalar offset
* @returns {integer} INFO
*/
function dpbequ( uplo, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om ) { // eslint-disable-line max-params -- Preserve the adopted fourteen-argument ndarray contract.
	var small;
	var large;
	var value;
	var ai;
	var j;
	if ( N === 0 ) {
		SCOND[oc] = 1;
		AMAX[om] = 0;
		return 0;
	}
	ai = o + ((uplo === 121) ? KD*r : 0);
	small = AB[ai];
	large = small;
	for ( j = 0; j < N; j++ ) {
		value = AB[ai+(j*c)];
		S[os+(j*ss)] = value;
		if ( value < small ) {
			small = value;
		}
		if ( value > large ) {
			large = value;
		}
	}
	AMAX[om] = large;
	if ( small <= 0 ) {
		for ( j = 0; j < N; j++ ) {
			if ( S[os+(j*ss)] <= 0 ) {
				return j+1;
			}
		}
	}
	for ( j = 0; j < N; j++ ) {
		S[os+(j*ss)] = 1 / sqrt( S[os+(j*ss)] );
	}
	SCOND[oc] = sqrt(small) / sqrt(large);
	return 0;
}


// EXPORTS //

module.exports = dpbequ;
